-- Generated from medspa_booking.db.metadata; do not edit by hand.
CREATE TABLE medspas (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	name TEXT NOT NULL, 
	address TEXT NOT NULL, 
	phone_number TEXT NOT NULL, 
	email TEXT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE appointments (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	medspa_id INTEGER NOT NULL, 
	start_time TIMESTAMP WITH TIME ZONE NOT NULL, 
	status VARCHAR(20) DEFAULT 'scheduled' NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_appointments_status_allowed CHECK (status IN ('scheduled', 'completed', 'canceled')), 
	FOREIGN KEY(medspa_id) REFERENCES medspas (id)
);

CREATE INDEX ix_appointments_medspa_id ON appointments (medspa_id);

CREATE TABLE services (
	id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
	medspa_id INTEGER NOT NULL, 
	name TEXT NOT NULL, 
	description TEXT, 
	price INTEGER NOT NULL, 
	duration INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_services_name_nonblank CHECK (name ~ '[^[:space:]]'), 
	CONSTRAINT ck_services_price_nonnegative CHECK (price >= 0), 
	CONSTRAINT ck_services_duration_positive CHECK (duration > 0), 
	FOREIGN KEY(medspa_id) REFERENCES medspas (id)
);

CREATE INDEX ix_services_medspa_id ON services (medspa_id);

CREATE TABLE appointment_services (
	appointment_id INTEGER NOT NULL, 
	service_id INTEGER NOT NULL, 
	price_at_booking INTEGER NOT NULL, 
	duration_at_booking INTEGER NOT NULL, 
	PRIMARY KEY (appointment_id, service_id), 
	CONSTRAINT ck_appointment_services_price_nonnegative CHECK (price_at_booking >= 0), 
	CONSTRAINT ck_appointment_services_duration_positive CHECK (duration_at_booking > 0), 
	FOREIGN KEY(appointment_id) REFERENCES appointments (id) ON DELETE CASCADE, 
	FOREIGN KEY(service_id) REFERENCES services (id)
);
